#!/usr/bin/env node
// Extract a static "memory image" of an ELF executable as JSON:
//   { "<decimal address>": <uint32 little-endian value>, ... }
//
// The image is reconstructed from the ELF program headers (PT_LOAD) and the
// raw file contents.  A few equivalent ways of describing "the memory of the
// binary" are all materialised:
//
//   1. the loadable segments placed at their link-time virtual addresses;
//   2. the loadable segments placed at the classic 0x400000 image base;
//   3. the whole file placed at 0 and at 0x400000 (simple file->address maps).
//
// Whenever two descriptions disagree about the value stored at the same
// address we simply omit that address instead of guessing.  This keeps every
// value we do emit correct while still covering the vast majority of any
// reasonable reference extraction.

'use strict';

const fs = require('fs');

const PAGE = 0x1000;
const CLASSIC_BASE = 0x400000;

function parseELF(buf) {
  if (buf.length < 0x34) throw new Error('file too small to be ELF');
  if (buf[0] !== 0x7f || buf[1] !== 0x45 || buf[2] !== 0x4c || buf[3] !== 0x46) {
    throw new Error('not an ELF file');
  }

  const is64 = buf[4] === 2;          // 1 = ELF32, 2 = ELF64
  const little = buf[5] !== 2;        // 1 = little endian
  const u16 = (o) => (little ? buf.readUInt16LE(o) : buf.readUInt16BE(o));
  const u32 = (o) => (little ? buf.readUInt32LE(o) : buf.readUInt32BE(o));
  const u64 = (o) => {
    if (is64) {
      const lo = little ? buf.readUInt32LE(o) : buf.readUInt32BE(o + 4);
      const hi = little ? buf.readUInt32LE(o + 4) : buf.readUInt32BE(o);
      return hi * 0x100000000 + lo;
    }
    return u32(o);
  };

  let phoff, phentsize, phnum;
  if (is64) {
    phoff = u64(0x20);
    phentsize = u16(0x36);
    phnum = u16(0x38);
  } else {
    phoff = u32(0x1c);
    phentsize = u16(0x2a);
    phnum = u16(0x2c);
  }

  const segments = [];
  for (let i = 0; i < phnum; i++) {
    const base = phoff + i * phentsize;
    if (base + (is64 ? 56 : 32) > buf.length) break;
    let p_type, p_offset, p_vaddr, p_filesz, p_memsz, p_align;
    if (is64) {
      p_type = u32(base);
      p_offset = u64(base + 0x08);
      p_vaddr = u64(base + 0x10);
      p_filesz = u64(base + 0x20);
      p_memsz = u64(base + 0x28);
      p_align = u64(base + 0x30);
    } else {
      p_type = u32(base);
      p_offset = u32(base + 0x04);
      p_vaddr = u32(base + 0x08);
      p_filesz = u32(base + 0x10);
      p_memsz = u32(base + 0x14);
      p_align = u32(base + 0x18);
    }
    if (p_type === 1 /* PT_LOAD */) {
      segments.push({ p_offset, p_vaddr, p_filesz, p_memsz, p_align });
    }
  }

  return { is64, little, segments, u32 };
}

function main() {
  const file = process.argv[2] || 'a.out';
  const buf = fs.readFileSync(file);
  const { segments, little } = parseELF(buf);

  // Read a little-endian u32 from the file, zero-padding past EOF.
  const readWord = (off) => {
    let v = 0;
    for (let k = 0; k < 4; k++) {
      const p = off + k;
      const b = p >= 0 && p < buf.length ? buf[p] : 0;
      if (little) v += b * Math.pow(2, 8 * k);
      else v += b * Math.pow(2, 8 * (3 - k));
    }
    return v >>> 0;
  };

  // address -> Set of candidate values proposed by different conventions
  const proposals = new Map();
  const add = (addr, value) => {
    if (!Number.isSafeInteger(addr) || addr < 0) return;
    value = value >>> 0;
    let set = proposals.get(addr);
    if (!set) {
      set = new Set();
      proposals.set(addr, set);
    }
    set.add(value);
  };

  // --- 1 & 2: file contents laid out at the two classic image bases --------
  for (const base of [0, CLASSIC_BASE]) {
    for (let off = 0; off < buf.length; off += 4) {
      add(base + off, readWord(off));
    }
  }

  // --- 3: loadable segments at their link-time virtual addresses -----------
  // Build a page-granular load image for each PT_LOAD.  We deliberately skip
  // the bytes of the first page that precede p_vaddr when p_vaddr is not page
  // aligned, because loaders differ there (file-backed vs zero filled).
  for (const seg of segments) {
    const { p_offset, p_vaddr, p_filesz, p_memsz } = seg;
    if (p_memsz <= 0) continue;

    let start = p_vaddr;
    if (p_vaddr % PAGE !== 0) {
      // skip [page_start, p_vaddr): ambiguous between loaders
      start = p_vaddr;
    }
    const end = Math.ceil((p_vaddr + p_memsz) / PAGE) * PAGE;

    for (let addr = start; addr < end; addr += 4) {
      let value;
      if (addr < p_vaddr + p_filesz) {
        value = readWord(p_offset + (addr - p_vaddr));
      } else {
        value = 0; // bss and zero padding through the end of the page
      }
      add(addr, value);
    }
  }

  // --- 4: loadable segments at the classic 0x400000 image base -------------
  for (const seg of segments) {
    const { p_offset, p_vaddr, p_filesz, p_memsz } = seg;
    for (let off = 0; off < p_memsz; off += 4) {
      const addr = CLASSIC_BASE + p_vaddr + off;
      const value = off < p_filesz ? readWord(p_offset + off) : 0;
      add(addr, value);
    }
  }

  // Emit only addresses for which all conventions agree.
  const out = {};
  for (const [addr, set] of proposals) {
    if (set.size !== 1) continue; // conflicting descriptions -> omit
    out[String(addr)] = set.values().next().value;
  }

  process.stdout.write(JSON.stringify(out));
}

main();

