e_phentsize,e_phnum=struct.unpack_from('<HH',buf,0x36)[0],struct.unpack_from('<H',buf,0x38)[0]
e_shoff=struct.unpack_from('<Q',buf,0x28)[0]
e_shentsize,e_shnum,e_shstrndx=struct.unpack_from('<HHH',buf,0x3a)
