    o=e_phoff+i*e_phentsize
    p_type,p_flags,p_offset,p_vaddr,p_paddr,p_filesz,p_memsz,p_align=struct.unpack_from('<IIQQQQQQ',buf,o)
    if p_type==1: segs.append(dict(offset=p_offset,vaddr=p_vaddr,filesz=p_filesz,memsz=p_memsz,align=p_align))
