for i in range(e_shnum):
    o=e_shoff+i*e_shentsize
    name,typ,flags,addr,off,size,link,info,align,entsize=struct.unpack_from('<IIQQQQIIQQ',buf,o)
    shs.append(dict(name=name,typ=typ,flags=flags,addr=addr,off=off,size=size,align=align))

def word(off):
    b=buf[off:off+4]
    return int.from_bytes(b.ljust(4,b'\0'),'little')

def whole(base):
    return {base+i:word(i) for i in range(0,len(buf)-3,4)}

def segs_at(base, use_memsz=True, zeros=True, iterate_filesz_only=False):
    d={}
    for s in segs:
        n=s['memsz'] if use_memsz else s['filesz']
        for off in range(0,n,4):
            a=base+s['vaddr']+off
            if off<s['filesz']: v=word(s['offset']+off)
            else:
                if not zeros: continue
                v=0
            d[a]=v
    return d

def page_image(base,kernel):
    d={};P=0x1000
    for s in segs:
        v=s['vaddr'];ms=s['memsz'];fs=s['filesz'];fo=s['offset']
        if ms<=0: continue
        start=(v//P)*P
        end=((v+ms+P-1)//P)*P
        if not kernel:
            # unicorn: map pages zeroed, write segment at v
            for a in range(start,end,4):
                if v<=a<v+fs: d[base+a]=word(fo+(a-v))
                else: d[base+a]=0
        else:
            for a in range(start,end,4):
                f=fo-(v-start)+(a-start)
                if a>=v and a<v+fs:
                    d[base+a]=word(fo+(a-v))
                elif a<v:
                    # file-congruent pre-extension
                    d[base+a]=word(f) if f>=0 else 0
                else:
                    d[base+a]=0
    return d

def sections(base,alloc_only=True,contents_only=True):
    d={}
    for s in shs:
        if alloc_only and not (s['flags']&2): continue
        if contents_only and s['typ']==8: continue  # NOBITS
        # only sections with a meaningful address
        for off in range(0,s['size'],4):
            d[base+s['addr']+off]=word(s['off']+off)
    return d

def sections_bss(base):
    d={}
    for s in shs:
        if not (s['flags']&2): continue
        if s['typ']==8:
            for off in range(0,s['size'],4): d[base+s['addr']+off]=0
        else:
            for off in range(0,s['size'],4): d[base+s['addr']+off]=word(s['off']+off)
    return d

