  // page-granular image
  for (const seg of segments) {
    const { p_offset, p_vaddr, p_filesz, p_memsz } = seg;
    if (p_memsz <= 0) continue;
    const start = Math.floor(p_vaddr / PAGE) * PAGE;
    const end = Math.ceil((p_vaddr + p_memsz) / PAGE) * PAGE;

    for (const kernelStyle of [false, true]) {
      for (let a = start; a < end; a += 4) {
        let value;
        if (a >= p_vaddr && a < p_vaddr + p_filesz) {
          value = readWord(p_offset + (a - p_vaddr));
